use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl AssocOp { # [doc = " Creates a new AssocOp from a token."] pub fn from_token (t : & Token) -> Option < AssocOp > { use AssocOp :: * ; match t . kind { token :: Eq => Some (Assign) , token :: Plus => Some (Binary (BinOpKind :: Add)) , token :: Minus => Some (Binary (BinOpKind :: Sub)) , token :: Star => Some (Binary (BinOpKind :: Mul)) , token :: Slash => Some (Binary (BinOpKind :: Div)) , token :: Percent => Some (Binary (BinOpKind :: Rem)) , token :: Caret => Some (Binary (BinOpKind :: BitXor)) , token :: And => Some (Binary (BinOpKind :: BitAnd)) , token :: Or => Some (Binary (BinOpKind :: BitOr)) , token :: Shl => Some (Binary (BinOpKind :: Shl)) , token :: Shr => Some (Binary (BinOpKind :: Shr)) , token :: PlusEq => Some (AssignOp (AssignOpKind :: AddAssign)) , token :: MinusEq => Some (AssignOp (AssignOpKind :: SubAssign)) , token :: StarEq => Some (AssignOp (AssignOpKind :: MulAssign)) , token :: SlashEq => Some (AssignOp (AssignOpKind :: DivAssign)) , token :: PercentEq => Some (AssignOp (AssignOpKind :: RemAssign)) , token :: CaretEq => Some (AssignOp (AssignOpKind :: BitXorAssign)) , token :: AndEq => Some (AssignOp (AssignOpKind :: BitAndAssign)) , token :: OrEq => Some (AssignOp (AssignOpKind :: BitOrAssign)) , token :: ShlEq => Some (AssignOp (AssignOpKind :: ShlAssign)) , token :: ShrEq => Some (AssignOp (AssignOpKind :: ShrAssign)) , token :: Lt => Some (Binary (BinOpKind :: Lt)) , token :: Le => Some (Binary (BinOpKind :: Le)) , token :: Ge => Some (Binary (BinOpKind :: Ge)) , token :: Gt => Some (Binary (BinOpKind :: Gt)) , token :: EqEq => Some (Binary (BinOpKind :: Eq)) , token :: Ne => Some (Binary (BinOpKind :: Ne)) , token :: AndAnd => Some (Binary (BinOpKind :: And)) , token :: OrOr => Some (Binary (BinOpKind :: Or)) , token :: DotDot => Some (Range (RangeLimits :: HalfOpen)) , token :: DotDotEq | token :: DotDotDot => Some (Range (RangeLimits :: Closed)) , token :: LArrow => Some (Binary (BinOpKind :: Lt)) , _ if t . is_keyword (kw :: As) => Some (Cast) , _ => None , } } # [doc = " Gets the precedence of this operator"] pub fn precedence (& self) -> ExprPrecedence { use AssocOp :: * ; match * self { Cast => ExprPrecedence :: Cast , Binary (bin_op) => bin_op . precedence () , Range (_) => ExprPrecedence :: Range , Assign | AssignOp (_) => ExprPrecedence :: Assign , } } # [doc = " Gets the fixity of this operator"] pub fn fixity (& self) -> Fixity { use AssocOp :: * ; match * self { Assign | AssignOp (_) => Fixity :: Right , Binary (binop) => binop . fixity () , Cast => Fixity :: Left , Range (_) => Fixity :: None , } } pub fn is_comparison (& self) -> bool { use AssocOp :: * ; match * self { Binary (binop) => binop . is_comparison () , Assign | AssignOp (_) | Cast | Range (_) => false , } } pub fn is_assign_like (& self) -> bool { use AssocOp :: * ; match * self { Assign | AssignOp (_) => true , Cast | Binary (_) | Range (_) => false , } } # [doc = " This operator could be used to follow a block unambiguously."] # [doc = ""] # [doc = " This is used for error recovery at the moment, providing a suggestion to wrap blocks with"] # [doc = " parentheses while having a high degree of confidence on the correctness of the suggestion."] pub fn can_continue_expr_unambiguously (& self) -> bool { use AssocOp :: * ; use BinOpKind :: * ; matches ! (self , Assign | Binary (BitXor | Div | Rem | Shr | Le | Gt | Ge) | AssignOp (_) | Cast) } }